13	async function ownedServer(serverId: string) {
14	  const user = await requireUser();
15	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
16	  if (!server) throw new Error("Not found");
17	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
18	  return { user, server };
19	}
