40	// ---------- Snapshots ----------
41	
42	/**
43	 * The ONE snapshot-name normalisation, applied identically on every path.
44	 *
45	 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
46	 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
47	 * this module accepts but the worker rejects is a job that reports QUEUED to the
48	 * customer and then dies in the worker with a message they never see. Delete and
49	 * rollback used to pass the raw argument straight through: a TypeScript parameter
50	 * type is not validation, and these are reachable with any string at all.
51	 */
52	function cleanSnapshotName(name: unknown): string {
53	  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
54	}
55	
56	const SNAPSHOT_NAME_ERROR =
57	  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
58	  "Pick the snapshot from the list on the server page rather than typing its name.";
59	
60	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
61	  const { user, server } = await ownedServer(serverId);
62	  const clean = cleanSnapshotName(name);
63	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
64	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
65	    return { error: "Server must be running or stopped." };
66	  }
67	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
68	  if (!res.error) {
69	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
70	    revalidatePath(`/dashboard/servers/${serverId}`);
71	  }
72	  return res;
73	}
