33	/**
34	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
35	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
36	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
37	 * this it existed only as a copy of the same number hardcoded on the IP page.
38	 */
39	export const OVH_IP_UNIT_COST_CENTS = 239;
