200	async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
201	  let cloudflareToken: string | null = null;
202	  let acmeEmail: string | null = null;
203	  const knownDomains: string[] = [];
204	  const notes: string[] = [];
205	
206	  try {
207	    const user = await db.user.findUnique({
208	      where: { id: userId },
209	      select: { id: true, email: true, cloudflareTokenEnc: true },
210	    });
211	    if (user) {
212	      // The account email is the ACME contact. This is what turns Let's
213	      // Encrypt's expiry warnings back on; without it a certificate that stops
214	      // renewing is only discovered by a visitor.
215	      acmeEmail = user.email ?? null;
216	      const resolved = await resolveCloudflareToken(user);
217	      if (resolved.token) {
218	        cloudflareToken = resolved.token;
219	        notes.push("your connected Cloudflare account is available, so wildcard certificates can be issued automatically (DNS-01)");
220	      } else {
221	        notes.push(
222	          "Cloudflare is not connected, so a wildcard certificate (needed when an app gives each tenant its own subdomain) cannot be issued automatically — connect it in Settings and we can finish that for you"
223	        );
224	      }
225	    }
226	  } catch (e) {
227	    // A DB hiccup here must never fail a migration — it only costs a rung.
228	    console.error("[migrate] could not resolve Cloudflare/ACME inputs", e);
229	    notes.push("we could not read your Cloudflare connection just now, so certificates were issued without it");
230	  }
231	
232	  try {
233	    const domains = await db.domain.findMany({
234	      where: { userId },
235	      select: { name: true },
236	      orderBy: { name: "asc" },
237	      take: 50,
238	    });
239	    for (const d of domains) if (d.name) knownDomains.push(d.name);
240	  } catch (e) {
241	    console.error("[migrate] could not load registered domains", e);
