390	/**
391	 * Is this migration abandoned — unfinished, with nothing left that could ever
392	 * finish it?
393	 *
394	 * WHY THIS EXISTS. Two documents promise the same thing in the same words:
395	 * `lib/actions-migrate.ts` ("They are CLEARED by the worker the moment the
396	 * migration finishes — success or failure — so a completed Migration row never
397	 * retains usable credentials") and this file's own header. Both are true for
398	 * every path that reaches `runMigration`'s try/catch. Neither is true for the
399	 * path where the worker never reaches it:
400	 *
401	 *   worker crash / restart  →  `reapStuckJobs` (worker/index.ts) re-QUEUEs the
402	 *   MIGRATE job  →  it crashes again  →  `attempts >= MAX_ATTEMPTS`  →  the job
403	 *   is marked FAILED and handed to `reconcileFailedJob`, which handles RESIZE and
404	 *   DISK_EXPAND and returns immediately for everything else.
405	 *
406	 * Nothing then touches the Migration row again. It keeps `status: "RUNNING"`
407	 * forever — the customer's wizard polls a progress bar that will never move — and
408	 * it keeps `sourcePasswordEnc`, which is the ROOT SSH PASSWORD OF ANOTHER
409	 * PROVIDER'S LIVE SERVER, encrypted at rest but retained indefinitely for a run
410	 * that ended hours ago. "Cleared when the run ends, success or failure" has to
411	 * include the failure mode where nothing was there to clear it.
412	 *
413	 * Pure so the rule is testable without a database, a worker or a clock.
414	 */
415	export function isAbandonedMigration(m: AbandonedMigrationInput): boolean {
416	  if (m.finishedAt) return false;
417	  if (m.status !== "PENDING" && m.status !== "RUNNING") return false;
418	  // Something can still finish it — leave it alone however long it takes.
419	  if (m.hasLiveJob) return false;
420	  return m.now - m.createdAt.getTime() >= (m.maxAgeMs ?? MIGRATION_ABANDON_MS);
