437	    where: { finishedAt: null, status: { in: ["PENDING", "RUNNING"] } },
438	    select: { id: true, userId: true, status: true, createdAt: true, finishedAt: true, items: true, log: true },
439	    orderBy: { createdAt: "asc" },
440	    take: 100,
441	  });
442	  if (!rows.length) return 0;
443	
444	  const now = Date.now();
445	  let reaped = 0;
446	  for (const m of rows) {
