503	 *
504	 * WHY THIS EXISTS. `runPostCutoverTls` was written for exactly this job and had
505	 * exactly one enqueue line — **inside a comment**. So it was dead code, and a
506	 * customer who migrated, then pointed their DNS a day later, never got the
507	 * certificate that could not be issued during the run: their first HTTPS visit
508	 * was a browser warning, forever.
509	 *
510	 * That was bad on its own. It became worse on 2026-07-26, when the migration
511	 * report's cutover instructions were rewritten to tell the customer, in plain
512	 * words, that "Nxeon issues the certificate automatically within about 30 minutes
513	 * of the change, and nothing else is needed." That sentence was false the moment
514	 * it shipped. `sslSweep` does NOT cover this case — it walks `db.sslCertificate`
515	 * rows, and a migration never writes one. A promise the product does not keep is
516	 * the same defect as a success this engine did not verify, so the promise is made
517	 * true here rather than walked back in the copy.
518	 *
519	 * Safe to run repeatedly by construction: the pass copies nothing, never touches
520	 * the source server, never rewrites `Migration.status`, and certbot's
521	 * `--keep-until-expiring` makes an already-certified domain a no-op.
522	 */
523	export async function postCutoverTlsSweep(): Promise<void> {
524	  // Settled here rather than in its own registered sweep because this function is
525	  // the migration subsystem's ONLY periodic entry point (worker/index.ts calls it
526	  // every 30 minutes) and an unfinished migration holding a source root password
527	  // must not wait for a new registration to be plumbed in. It is wrapped so a
528	  // failure here can never stop the certificate pass that follows.
529	  await reapAbandonedMigrations().catch((e) => console.error("[migrate] abandoned-migration sweep failed:", e));
530	
531	  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);
532	  const runningServerIds = (
533	    await db.server.findMany({ where: { status: "RUNNING" }, select: { id: true } })
534	  ).map((s) => s.id);
535	  if (!runningServerIds.length) return;
536	
537	  const candidates = await db.migration.findMany({
538	    where: {
539	      status: { in: ["DONE", "COMPLETED_WITH_ISSUES"] },
540	      finishedAt: { gte: since },
541	      // SSH is the first thing this pass does. A server that is not running
542	      // cannot answer, and the attempt would occupy the strictly-serial worker
543	      // until the connection times out. `Migration.serverId` is a bare column
544	      // with no Prisma relation, so the running set is resolved separately.
545	      serverId: { in: runningServerIds },
546	    },
547	    select: { id: true, items: true, serverId: true },
548	    orderBy: { finishedAt: "desc" },
549	    take: 50,
550	  });
551	
552	  // ONE pass per target server, not per migration. A customer who retried a
553	  // migration three times has three rows pointing at the same box; certifying it
554	  // once certifies it for all of them, and the first live run queued four
555	  // redundant SSH sessions for a single server. Newest first, since that run's
556	  // published site config is the one on disk.
557	  const seenServers = new Set<string>();
558	
559	  for (const m of candidates) {
560	    // Already fully certified — a previous pass found nothing outstanding.
561	    if ((m.items as { tlsSettled?: boolean } | null)?.tlsSettled) continue;
562	    if (seenServers.has(m.serverId)) continue;
563	    seenServers.add(m.serverId);
564	
565	    // Don't stack attempts. A job still queued, or one tried recently, means the
566	    // answer is already on its way; certbot rate limits are real and shared.
567	    const recent = await db.job.findFirst({
568	      where: {
569	        type: "MIGRATE",
570	        createdAt: { gte: new Date(Date.now() - TLS_RETRY_MS) },
571	        payload: { path: ["migrationId"], equals: m.id },
572	      },
573	      select: { id: true },
574	    });
575	    if (recent) continue;
576	
577	    await db.job
578	      .create({ data: { type: "MIGRATE", payload: { migrationId: m.id, phase: "tls" } } })
579	      .catch((e) => console.error(`[migrate] could not enqueue TLS pass for ${m.id}:`, e));
580	  }
581	}
