586	  const paths = items.paths ?? [];
587	  const target = migration.server;
588	  const targetName = target ? target.label || target.hostname : "your server";
589	
590	  // The post-cutover certificate pass shares this handler (and therefore the
591	  // already-registered MIGRATE JobType) but is NOT a migration: it copies
592	  // nothing and must never fall through into the transfer below.
593	  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
594	    try {
595	      // HARD CEILING. This worker is strictly serial: whatever is in this
596	      // function is the only thing the platform is doing. The pass opens SSH to a
597	      // customer's box and runs certbot, and on the sweep's first live run a
598	      // single unresponsive target left the job RUNNING through two reap cycles
599	      // — with a new customer's provisioning job queued behind it. A background
600	      // nicety must never be able to stall the queue that provisions servers.
601	      await Promise.race([
602	        runPostCutoverTls(migration, items),
