607	    } catch (e) {
608	      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
609	      // Swallowed on purpose: a failed certificate retry must not mark the
610	      // customer's finished migration as failed, and must not make the job loop
611	      // retry a phase that will keep failing for the same reason. The sweep will
612	      // come back to it on its own schedule.
