143	/**
144	 * Decide whether an existing record is "the same kind" as one we manage, so an
145	 * upsert updates it in place rather than creating a duplicate. TXT records are
146	 * matched by their leading tag (SPF/DKIM/DMARC/ownership), MX by the mail host
147	 * it points at — so we never clobber a customer's unrelated records at the apex.
148	 */
149	function sameKind(desired: CfDnsInput, existing: CfRecord): boolean {
150	  if (existing.type !== desired.type) return false;
151	  // A: an existing A at this exact name IS the record we manage — repointing a
152	  // hostname at a new server must overwrite the old address, not add a second
153	  // one (two A records would round-robin between the old and new box).
154	  if (desired.type === "A") return true;
155	  if (desired.type === "MX") {
156	    return unquote(existing.content).replace(/\.$/, "").toLowerCase() ===
157	      desired.content.replace(/\.$/, "").toLowerCase();
158	  }
159	  const want = desired.content.toLowerCase();
160	  const have = unquote(existing.content).toLowerCase();
161	  for (const tag of ["nxeon-verify=", "v=spf1", "v=dkim1", "v=dmarc1"]) {
162	    if (want.startsWith(tag)) return have.startsWith(tag);
163	  }
164	  // No recognised tag — fall back to an exact name+type match (single record).
165	  return true;
166	}
167	
168	/**
169	 * Create or update each desired record in the given zone. For every record we
170	 * list the existing records at that exact name+type, update the one of the same
171	 * kind if present (PUT), else create a new one (POST). Returns one result row
172	 * per input describing what happened. Throws CloudflareError on API failure.
173	 */
174	export async function cfUpsertRecords(
175	  token: string,
176	  zoneId: string,
177	  records: CfDnsInput[],
178	): Promise<CfUpsertResult[]> {
179	  const out: CfUpsertResult[] = [];
180	
181	  for (const rec of records) {
182	    const existing = await cfRequest<CfRecord[]>(
183	      token,
184	      "GET",
185	      `/zones/${zoneId}/dns_records?type=${rec.type}&name=${encodeURIComponent(rec.name)}&per_page=100`,
186	    );
187	    const match = Array.isArray(existing) ? existing.find((e) => sameKind(rec, e)) : undefined;
188	
189	    const body: Record<string, unknown> = {
190	      type: rec.type,
191	      name: rec.name,
192	      content: rec.content,
193	      ttl: 1, // 1 = automatic
194	    };
195	    if (rec.type === "MX") body.priority = rec.priority ?? 10;
196	    // DNS-only unless a caller explicitly asks to proxy (none do today).
197	    if (rec.type === "A") body.proxied = rec.proxied === true;
198	
199	    if (match) {
200	      await cfRequest(token, "PUT", `/zones/${zoneId}/dns_records/${match.id}`, body);
201	      out.push({ name: rec.name, type: rec.type, action: "updated" });
202	    } else {
203	      await cfRequest(token, "POST", `/zones/${zoneId}/dns_records`, body);
204	      out.push({ name: rec.name, type: rec.type, action: "created" });
205	    }
206	  }
207	
208	  return out;
209	}
